    if conflicts:
        for shift_a, shift_b in conflicts:
            print(
                f"{shift_a.name}: {shift_a.date} {shift_a.start}-{shift_a.end} "
                f"overlaps {shift_b.date} {shift_b.start}-{shift_b.end}"
            )
        return 1
    else:
        print("no conflicts")
        return 0


if __name__ == "__main__":
